    suppressConfirmHereForSession = false;
    isShareEventModalVisible = new BehaviorSubject(false);
    isLoadingModalVisible = new BehaviorSubject(false);
    activeSidebarContent = new BehaviorSubject('none');
    sidebarNavigationStack = new BehaviorSubject([]);
    modernMenuDarkMode = new BehaviorSubject(false);
    themeStorageKey = 'mediasfu-angular-theme';
    sidebarEmbeddedModalContentStyle = {
        border: 'none',
        boxShadow: 'none',
        background: 'transparent',
        borderRadius: '0',
        backdropFilter: 'none',
    };
    resolvePreferredTheme = () => {
        if (typeof window !== 'undefined') {
            try {
                const storedTheme = window.localStorage.getItem(this.themeStorageKey);
                if (storedTheme === 'dark') {
                    return true;
                }
                if (storedTheme === 'light') {
                    return false;
                }
            }
            catch {
                // Ignore storage access failures and fall back to the default room theme.
            }
        }
        return true;
    };
    updateModernThemeDarkMode = (value) => {
        this.modernMenuDarkMode.next(value);
        if (typeof window !== 'undefined') {
            try {
                window.localStorage.setItem(this.themeStorageKey, value ? 'dark' : 'light');
            }
            catch {
                // Ignore storage access failures and keep the in-memory theme state.
            }
        }
        this.messageWidget = this.buildMessageWidget();
        this.updateButtonState('modernThemeDarkMode', value);
        void this.updateRecordButtons();
        this.updateControlBroadcastButtons();
        this.updateControlChatButtons();
        this.cdr.detectChanges();
    };
    // Recording Options
    recordingMediaOptions = new BehaviorSubject('video');
    recordingAudioOptions = new BehaviorSubject('all');
    recordingVideoOptions = new BehaviorSubject('all');
    recordingVideoType = new BehaviorSubject('fullDisplay');
    recordingVideoOptimized = new BehaviorSubject(false);
    recordingDisplayType = new BehaviorSubject('video');
    recordingAddHLS = new BehaviorSubject(true);
    recordingNameTags = new BehaviorSubject(true);
    recordingBackgroundColor = new BehaviorSubject('#83c0e9');
    recordingNameTagsColor = new BehaviorSubject('#ffffff');
    recordingAddText = new BehaviorSubject(false);
    recordingCustomText = new BehaviorSubject('Add Text');
    recordingCustomTextPosition = new BehaviorSubject('top');
