        if (!inputs || typeof inputs !== 'object') {
            return this.injector;
        }
        const inj = Injector.create({
            providers: Object.keys(inputs).map((key) => ({ provide: key, useValue: inputs[key] })),
            parent: this.injector,
        });
        return inj;
